select jsonb_build_object(
'provincias',(select count(*) from cuidared.provincia),
'municipios',(select count(*) from cuidared.municipio),
'diferencias_provincias',(select count(*) from provincias_esperadas e full join cuidared.provincia p on p.provincia_cod=e.codigo where p.provincia_cod is null or e.codigo is null or p.nombre is distinct from e.nombre),
'diferencias_municipios',(select count(*) from municipios_esperados e full join cuidared.municipio m on m.municipio_cod=e.codigo where m.municipio_cod is null or e.codigo is null or m.nombre is distinct from e.nombre or m.provincia_cod is distinct from e.provincia),
'codigos_provincia_invalidos',(select count(*) from cuidared.provincia where provincia_cod !~ '^[0-9]{2}$'),
'codigos_municipio_invalidos',(select count(*) from cuidared.municipio where municipio_cod !~ '^[0-9]{4}$' or left(municipio_cod,2) <> provincia_cod),
'municipios_sin_provincia',(select count(*) from cuidared.municipio m left join cuidared.provincia p using(provincia_cod) where p.provincia_cod is null),
'tablas_temporales_restantes',(select count(*) from pg_catalog.pg_class where relpersistence='t' and relname in ('one_2021_provincia','one_2021_municipio')),
'controles_tablas',(select jsonb_agg(jsonb_build_object('tabla',c.relname,'rls',c.relrowsecurity,'permisos',c.relacl::text,'politicas',(select count(*) from pg_catalog.pg_policy p where p.polrelid=c.oid))) from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace where n.nspname='cuidared' and c.relname in ('provincia','municipio'))
) as verificacion;
